            hydrated = []
            for item in items:
                item = self.hydrate(item, "computeConfig", f"https://compute.googleapis.com/compute/v1/{scope}", scope)
                config = item.get("computeConfig", {})
                for field in ("commonInstanceMetadata", "defaultServiceAccount", "xpnProjectStatus"):
